// `npm run factory -- quality-score [--metrics <dir>] [--escaped <issues.json>] [--out <file>] [--check]`
// docs/QUALITY_SCORE.md (plan 5.9): a table per surface (tests per level, open escaped defects, flake count), generated by this
// script and never typed by hand. Inputs: the surface map, the test files on disk, the feature atlas, factory/quarantine.yaml,
// and optionally the metrics store (flake counts) and a JSON list of open issues labelled `escaped` (`gh issue list --json`).
// `--check` regenerates from the repository alone and fails when the committed file differs (the nightly docs-freshness step).
import { writeFileSync } from "node:fs";
import { readText, walk } from "./lib/repo.mjs";
import { matchAny } from "./lib/glob.mjs";
import { loadFeatures } from "./lib/spec.mjs";
import { loadSurfaceMap } from "./surfaces.mjs";
import { LEVELS, levelOf, loadQuarantine } from "./test-health.mjs";
import { readMetrics } from "./metrics.mjs";

/** Rule ids; each has a negative test tagged `@guard quality-score/<id>` (doctor checks). */
export const RULES = ["fresh"];

export const OUT = "docs/QUALITY_SCORE.md";
const TEST_FILE = /\.(test|spec)\.(ts|tsx|mts|mjs|js)$/;

export function buildQualityScore(root, { metricsDir, escaped = [] } = {}) {
  const map = loadSurfaceMap(root);
  const features = loadFeatures(root).data.features ?? [];
  const tests = walk(root).filter((f) => TEST_FILE.test(f) && !/\/fixtures\//.test(f));
  const q = loadQuarantine(root).entries;
  const flakyBySurface = {};
  if (metricsDir)
    for (const l of readMetrics(metricsDir).lines)
      for (const s of String(l.extra?.flaky_surfaces ?? "")
        .split(",")
        .filter(Boolean))
        flakyBySurface[s] = (flakyBySurface[s] ?? 0) + 1;
  const levels = [...new Set(LEVELS.map((l) => l.level))];
  const rows = Object.entries(map.surfaces).map(([key, s]) => {
    // A test belongs to a surface when it sits under the surface's paths or an atlas entry for that surface lists it.
    const listed = new Set(features.filter((f) => (f.surfaces ?? []).includes(key)).flatMap((f) => f.tests ?? []));
    const mine = tests.filter((t) => matchAny(s.paths, t) || listed.has(t));
    const perLevel = Object.fromEntries(levels.map((lv) => [lv, 0]));
    for (const t of mine) {
      const lvl = LEVELS.find((l) => l.name === levelOf(t))?.level;
      if (lvl) perLevel[lvl]++;
    }
    return {
      key,
      perLevel,
      features: features.filter((f) => (f.surfaces ?? []).includes(key)).length,
      quarantined: q.filter((e) => mine.some((t) => String(e.test).startsWith(`${t} `))).length,
      escaped: escaped.filter((i) => (i.labels ?? []).some((l) => (l.name ?? l) === `surface:${key}`)).length,
      flaky: metricsDir ? (flakyBySurface[key] ?? 0) : null,
    };
  });
  const md = [
    "# Quality score",
    "",
    "<!-- Generated by `npm run factory -- quality-score`. Do not edit by hand; the nightly fails when this file is stale. -->",
    "",
    "Test files per level and surface (levels: docs/PLAN.md 5.5), from the surface map, the test files on disk, the feature atlas",
    "and the quarantine list. Escaped defects and flake counts come from GitHub issues and the metrics store; the nightly publishes",
    "the version with those columns to the `factory-data` branch (`reports/QUALITY_SCORE.md`). Here they read `n/a`.",
    "",
    `| Surface | Features | ${levels.join(" | ")} | Quarantined | Escaped (open) | Flaky (nightly) |`,
    `| --- | ---: | ${levels.map(() => "---:").join(" | ")} | ---: | ---: | ---: |`,
    ...rows.map(
      (r) =>
        `| ${r.key} | ${r.features} | ${levels.map((lv) => r.perLevel[lv]).join(" | ")} | ${r.quarantined} | ${metricsDir || escaped.length ? r.escaped : "n/a"} | ${r.flaky ?? "n/a"} |`,
    ),
    "",
  ].join("\n");
  return { md, rows };
}

export function runQualityScore(root, args, out) {
  const opt = (f) => (args.indexOf(f) >= 0 ? args[args.indexOf(f) + 1] : undefined);
  const escaped = opt("--escaped") ? JSON.parse(readText(root, opt("--escaped")) ?? "[]") : [];
  const { md } = buildQualityScore(root, { metricsDir: opt("--metrics"), escaped });
  if (args.includes("--check")) {
    if ((readText(root, OUT) ?? "") === md) {
      out.log(`quality-score: PASS (${OUT} is current)`);
      return 0;
    }
    out.err(
      `quality-score: FAIL\n  x ${OUT} is stale: regenerating it from the repository gives a different table\n    fix: run 'npm run factory -- quality-score' and commit ${OUT}.`,
    );
    return 1;
  }
  const target = opt("--out") ?? OUT;
  writeFileSync(target.startsWith("/") ? target : `${root}/${target}`, md);
  out.log(`quality-score: wrote ${target}`);
  return 0;
}
